    private static void put(String sid, int cardType, String cfg) {
        CONFIGS.put(sid, cfg);
        CARD_TYPES.put(sid, cardType);
    }

    /** Verbatim cardConfig for sid, or null when no template (caller falls back to synthesis). */
    public static String cardConfig(String sid) {
        return sid == null ? null : CONFIGS.get(sid);
    }

    /** True cardType for sid (1=quickapp, 2=native provider, 100=seedling), or def when unknown. */
    public static int cardType(String sid, int def) {
        Integer v = sid == null ? null : CARD_TYPES.get(sid);
        return v == null ? def : v.intValue();
    }

